import java.util.Arrays
import java.util.Scanner

fun nextPermutation(idx: IntArray): Boolean {
    val n = idx.size
    for (i in n - 1 downTo 1) {
        if (idx[i] > idx[i - 1]) {
            val temp = idx[i]
            idx[i] = idx[i - 1]
            idx[i - 1] = temp
            Arrays.sort(idx, i, n)
            return true
        }
    }
    return false
}

