import kotlin.math.min

fun nextPermutation(array: IntArray): Boolean {
    var i = array.size - 1
    while (i > 0 && array[i - 1] >= array[i]) {
        i--
    }
    if (i <= 0) return false

    var j = array.size - 1
    while (array[j] <= array[i - 1]) {
        j--
    }
    val temp = array[i - 1]
    array[i - 1] = array[j]
    array[j] = temp

    j = array.size - 1
    while (i < j) {
        val temp2 = array[i]
        array[i] = array[j]
        array[j] = temp2
        i++
        j--
    }
    return true
}

